extracted_python_code:
active_customers_by_country = Customers.WHERE(
    (join_date >= "2023-01-01") & (status == 'Active')
).PARTITION(name="country_groups", by=country).CALCULATE(
    country=country,
    TAC=COUNT(Customers)
)

result = Transactions.WHERE(
    (transaction_type == 'buy') & (DATEDIFF("days", date_time, 'now') <= 10)
).CALCULATE(
    ticker_symbol=ticker.symbol
).PARTITION(name="ticker_groups", by=(ticker_symbol)).CALCULATE(
    ticker_symbol=ticker_symbol,
    num_buy_transactions=COUNT(Transactions)
).TOP_K(2, by=num_buy_transactions.DESC())

# Filter daily prices for the last 7 days, then partition by ticker type to calculate the average closing price for each type.
result = DailyPrices.WHERE(
    DATEDIFF("days", date, DATETIME('now')) < 7
).CALCULATE(
    ticker_type=ticker.ticker_type
).PARTITION(
    name="type_groups", by=(ticker_type)
).CALCULATE(
    ticker_type=ticker_type,
    average_closing_price=AVG(DailyPrices.close)
)

num_customers = Broker.CALCULATE(
    customer_count=COUNT(
        Customers.WHERE(
            (STARTSWITH(LOWER(name), 'j') | ENDSWITH(LOWER(name), 'ez')) &
            ENDSWITH(LOWER(state), 'a')
        )
    )
)

result = Transactions.WHERE(
    (date_time >= "2023-01-01") & (date_time < "2023-04-01")
).PARTITION(
    name="type_groups", by=(transaction_type)
).CALCULATE(
    transaction_type=transaction_type,
    num_distinct_customers=NDISTINCT(Transactions.customer_id),
    avg_shares=AVG(Transactions.shares)
).TOP_K(3, by=num_distinct_customers.DESC())

result = Transactions.WHERE(transaction_type == 'buy').PARTITION(name="customer_group", by=(customer_id)).CALCULATE(
    customer_id=customer_id
)

distinct_ticker_ids = DailyPrices.WHERE(date >= "2023-04-01").PARTITION(name="distinct_tickers", by=(ticker_id)).CALCULATE(
    ticker_id=ticker_id
)

top_countries_by_transaction_amount = Transactions.WHERE(
    DATEDIFF("days", date_time, DATETIME('now')) <= 30
).CALCULATE(
    country=customer.country,
    amount=amount
).PARTITION(
    name="country_groups", 
    by=country
).CALCULATE(
    country_name=country,
    number_of_transactions=COUNT(Transactions),
    total_transaction_amount=SUM(Transactions.amount)
).TOP_K(5, by=total_transaction_amount.DESC())

result = Broker.CALCULATE(
    num_transactions=COUNT(Transactions.WHERE(DATEDIFF("days", customer.join_date, DATETIME('now')) <= 70))
)

sales_by_model = Cars.WHERE(
    LIKE(UPPER(vin_number), '%M5%')
).PARTITION(
    name="car_models", by=(make, model)
).CALCULATE(
    make=make,
    model=model,
    number_of_sales=COUNT(Cars.sale_records)
)

result = Dealership.CALCULATE(
    avg_days_to_payment=ROUND(
        AVG(
            Sales.WHERE(HAS(payment) == 1).payment.CALCULATE(
                days_diff=DATEDIFF("days", sale_date, payment_date)
            ).days_diff
        ),
        2
    )
)

gpm_2023 = Dealership.CALCULATE(
    total_revenue=SUM(Sales.WHERE(YEAR(sale_date) == 2023).sale_price),
    total_cost=SUM(Sales.WHERE(YEAR(sale_date) == 2023).car.cost)
).CALCULATE(
    gpm=((total_revenue - total_cost) / total_cost) * 100
)

result = Sales.WHERE(
    HAS(car.inventory_snapshots.WHERE((snapshot_date == sale_date) & (is_in_inventory == False))) == 1
).TOP_K(
    1, by=sale_price.DESC()
).CALCULATE(
    make=car.make,
    model=car.model,
    sale_price=sale_price
)

result = Customers.WHERE(HAS(car_purchases) == 1).CALCULATE(
    customer_id=_id
)

cash_salespersons = Salespersons.WHERE(
    HAS(sales_made.payment.WHERE(payment_method == 'Cash')) == 1
).CALCULATE(
    salesperson_id=_id
)

weekend_payments_to_utility_company = Dealership.CALCULATE(
    num_payments=COUNT(
        PaymentsMade.WHERE(
            (vendor_name == 'Utility Company') & 
            ISIN(DAYNAME(payment_date), ('Saturday', 'Sunday'))
        )
    )
)

quarterly_sales_by_state = Sales.WHERE(YEAR(sale_date) == 2023).CALCULATE(
    customer_state=customer.state,
    quarter_start_date=IFF(
        MONTH(sale_date) <= 3, "2023-01-01",
        IFF(MONTH(sale_date) <= 6, "2023-04-01",
            IFF(MONTH(sale_date) <= 9, "2023-07-01", "2023-10-01")
        )
    )
).PARTITION(
    name="state_quarter_groups",
    by=(customer_state, quarter_start_date)
).CALCULATE(
    state=customer_state,
    quarter=quarter_start_date,
    total_sales=SUM(Sales.sale_price)
)

result = Drugs.CALCULATE(
    drug_name=drug_name,
    average_ddd=AVG(
        treatments_used_in.WHERE(
            (HAS(end_dt) == 1) & (DATEDIFF("days", start_dt, end_dt) > 0)
        ).CALCULATE(
            ddd=tot_drug_amt / DATEDIFF("days", start_dt, end_dt)
        ).ddd
    )
)

gmail_or_yahoo_patients_count = DermTreatment.CALCULATE(
    num_patients=COUNT(
        Patients.WHERE(
            (ENDSWITH(email, "@gmail.com") | ENDSWITH(email, "@yahoo.com"))
        )
    )
)

result = DermTreatment.CALCULATE(
    num_patients=COUNT(
        Patients.WHERE(
            HAS(
                treatments_received.WHERE(
                    (diagnosis.diag_name == 'Psoriasis vulgaris') & (drug.drug_type == 'biologic')
                )
            ) == 1
        )
    )
)

alice_treatments_last_6_months = Patients.WHERE(first_name == "Alice").CALCULATE(
    num_treatments=COUNT(treatments_received.WHERE(
        (start_dt >= DATETIME('now', 'start of month', '-6 months')) &
        (start_dt < DATETIME('now', 'start of month'))
    ))
)

avg_patient_weight = Drugs.WHERE(drug_name == 'Drugalin').CALCULATE(
    avg_weight=AVG(treatments_used_in.patient.weight_kg)
)

caw_male_patients = DermTreatment.CALCULATE(
    caw_male_patients=AVG(Patients.WHERE(gender == 'Male').weight_kg)
)

private_insured_patient_count = DermTreatment.CALCULATE(
    PIC=COUNT(Patients.WHERE((ins_type == 'private') & (gender == 'F')))
)

top_drug_by_adverse_events = Drugs.CALCULATE(
    drug_id=drug_id,
    drug_name=drug_name,
    num_adverse_events=COUNT(
        treatments_used_in.adverse_events.WHERE(
            (YEAR(reported_dt) == YEAR(treatment.start_dt)) &
            (MONTH(reported_dt) == MONTH(treatment.start_dt))
        )
    )
).TOP_K(1, by=num_adverse_events.DESC())

result = Drugs.WHERE(drug_type == 'biologic').treatments_used_in.doctor.PARTITION(name="states", by=loc_state).CALCULATE(
    state=loc_state
).ORDER_BY(loc_state.ASC())

recent_psoriasis_treatments_count = DermTreatment.CALCULATE(
    num_treatments=COUNT(
        Treatments.WHERE(
            (LIKE(LOWER(diagnosis.diag_name), '%psoriasis%')) &
            (HAS(drug.fda_appr_dt) == 1) &
            (DATEDIFF("months", end_dt, DATETIME('now')) <= 6) &
            (end_dt <= DATETIME('now'))
        )
    )
)

result = DermTreatment.CALCULATE(
    avg_patient_age=ROUND(AVG(
        Patients.WHERE(
            (gender == 'male') & (ins_type == 'private')
        ).CALCULATE(
            age=DATEDIFF("years", date_of_birth, DATETIME('now'))
        ).age
    ), 0)
)

average_amb_result = Ewallet.CALCULATE(
    average_balance=AVG(
        UserBalances.WHERE(
            DATEDIFF("days", updated_at, 'now') <= 7
        ).PARTITION(
            name="user_group", by=(user_id)
        ).CALCULATE(
            user_avg_balance=AVG(UserBalances.balance)
        ).user_avg_balance
    )
)

latest_user_balances = Users.CALCULATE(
    user_id=uid,
    latest_balance=balances.WHERE(
        RANKING(by=updated_at.DESC(), per="Users") == 1
    ).SINGULAR().balance
)

marketing_preferences = Users.CALCULATE(
    user_id=uid,
    marketing_opt_in=setting_snapshots.WHERE(
        RANKING(by=snapshot_date.DESC(), per="Users") == 1
    ).SINGULAR().marketing_opt_in
)

us_users_with_unread_promos = Users.WHERE(
    (LOWER(country) == 'us') &
    (HAS(notifications.WHERE((notification_type == 'promotional') & (status == 'unread'))) == 1)
).CALCULATE(
    username=username,
    total_unread_promotional_notifications=COUNT(
        notifications.WHERE((notification_type == 'promotional') & (status == 'unread'))
    )
)

result = Transactions.WHERE(
    (YEAR(created_at) == 2023) &
    (sender_type == 'user') &
    (status == 'completed')
).CALCULATE(
    month_date=DATETIME(created_at, 'start of month')
).PARTITION(
    name="monthly_transactions", by=(month_date)
).CALCULATE(
    month=month_date,
    num_active_users=NDISTINCT(Transactions.sender_id)
).ORDER_BY(
    month.ASC()
)

distinct_user_ids_with_transaction_notifications = Notifications.WHERE(notification_type == 'transaction').PARTITION(name="distinct_users", by=(user_id)).CALCULATE(
    user_id=user_id
)

top_merchants_by_amount = Transactions.WHERE(
    (receiver_type == 1) & (DATEDIFF("days", created_at, DATETIME('now')) <= 150)
).PARTITION(
    name="merchant_groups", by=(receiver_id)
).CALCULATE(
    merchant_name=MIN(Transactions.receiving_merchant.name),
    total_num_transactions=COUNT(Transactions),
    total_transaction_amount=SUM(Transactions.amount)
).TOP_K(2, by=total_transaction_amount.DESC())

avg_limits_for_earliest_snapshot = Ewallet.CALCULATE(
    earliest_date_2023=MIN(UserSettingSnapshots.WHERE(YEAR(snapshot_date) == 2023).snapshot_date)
).CALCULATE(
    avg_daily_limit=AVG(UserSettingSnapshots.WHERE(snapshot_date == earliest_date_2023).tx_limit_daily),
    avg_monthly_limit=AVG(UserSettingSnapshots.WHERE(snapshot_date == earliest_date_2023).tx_limit_monthly)
)

avg_session_duration_by_device = UserSessions.PARTITION(name="sessions_by_device", by=(device_type)).CALCULATE(
    device_type=device_type,
    avg_duration_seconds=AVG(UserSessions.CALCULATE(
        duration=DATEDIFF("seconds", session_start_ts, session_end_ts)
    ).duration)
)
